std::vector<std::vector<long long>> S(n+1, std::vector<long long>(n+1, 0));
S[0][0] = 1;
for (int i = 1; i <= n; ++i)
    for (int k = 1; k <= i; ++k)
        S[i][k] = S[i-1][k-1] + (long long)k * S[i-1][k];
// S[i][k] agora contém S(i,k), na mesma estrutura do triângulo de Pascal (Seção 2.2)

int n = 3, cores = 2;
long long total_fix = 0;
for (int g = 0; g < n; ++g) {          // g = quantas posições a rotação desloca
    int ciclos = std::gcd(g, n);        // std::gcd(0,n) == n: identidade tem n ciclos de tamanho 1
    total_fix += (long long)std::pow(cores, ciclos);
}
// órbitas = total_fix / n  (lema de Burnside)

