UnionFind uf(n);
long long custo = 0;
for (auto& [peso, u, v] : arestas) {
    if (uf.find(u) != uf.find(v)) {   // testa independência: não fecha ciclo
        uf.unite(u, v);
        custo += peso;
    }
}
